/// ORQUBE 공통 6개국어 번역 도우미.
/// 기존 라우팅/화면 클래스를 바꾸지 않고 화면 문자열만 변환합니다.
class OrqubeI18n {
  static String currentLanguage = 'ko';

  static void setLanguage(String? language) {
    currentLanguage = normalize(language);
  }

  static String nativeTranslation(String ko, String en) => pair(currentLanguage, ko, en);
  static String currentPair(String ko, String en) =>
      pair(currentLanguage, ko, en);

  static const supported = <String>['ko', 'en', 'ja', 'zh', 'fr', 'pt'];

  static String normalize(String? language) =>
      supported.contains(language) ? language! : 'ko';

  static String pair(String language, String ko, String en) {
    final lang = normalize(language);
    if (lang == 'ko') return ko;
    if (lang == 'en') return en;
    final row = _pairCatalog[ko];
    return row?[lang] ?? en;
  }

  static String key(String language, String key) {
    final lang = normalize(language);
    return _keys[key]?[lang] ?? _keys[key]?['en'] ?? key;
  }

  static String get searchLanguageTag {
    switch (currentLanguage) {
      case 'ja': return 'ja';
      case 'zh': return 'zh-CN';
      case 'fr': return 'fr';
      case 'pt': return 'pt';
      case 'en': return 'en';
      default: return 'ko';
    }
  }

